import type { VocabularyWord } from '@/types/models';

function w(
  word: string,
  definition: string,
  exampleSentence: string,
  topic: string,
  synonyms: string[],
  collocations: string[],
  pronunciationIpa: string,
  difficulty: VocabularyWord['difficulty']
): VocabularyWord {
  return {
    id: `v-${word.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
    word,
    definition,
    exampleSentence,
    topic,
    synonyms,
    collocations,
    pronunciationIpa,
    difficulty,
  };
}

